  "colleague_tracking": {
    "supporters_of_correct_answer_C": ["Colleague 1 (flipped from D)", "Colleague 3", "Colleague 6", "Colleague 8", "Colleague 10", "Colleague 11 (flipped from D)", "Colleague 12 (flipped from D)", "Colleague 15", "Colleague 18 (flipped from D)", "Colleague 19 (flipped from D)", "Colleague 20"],
